import json, threading, time, urllib.request
from http.server import BaseHTTPRequestHandler, HTTPServer

# 가짜 '경로 API' — 요청 경로로 응답을 고른다(진짜 서버 없이 실패를 만든다)
class Mock(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/route/slow":
            time.sleep(2)
        code = 503 if self.path == "/route/down" else 200
        body = json.dumps({"eta_min": 23} if code == 200 else {"error": "busy"}).encode()
        try:
            self.send_response(code); self.end_headers(); self.wfile.write(body)
        except ConnectionError:
            pass  # 앱이 먼저 끊은 경우(시간 초과)
    def log_message(self, *a): pass

srv = HTTPServer(("127.0.0.1", 0), Mock)
threading.Thread(target=srv.serve_forever, daemon=True).start()
base = f"http://127.0.0.1:{srv.server_port}"

def eta_text(path):  # 앱이 화면에 띄울 글자(시험 대상)
    try:
        with urllib.request.urlopen(base + path, timeout=1) as r:
            return f"{json.load(r)['eta_min']}분"
    except urllib.error.HTTPError:
        return "잠시 후 다시 시도"
    except Exception:
        return "응답 지연 — 이전 경로 유지"

for p in ["/route/ok", "/route/down", "/route/slow"]:
    print(p, "→", eta_text(p))
srv.shutdown()

# 출력
# /route/ok → 23분
# /route/down → 잠시 후 다시 시도
# /route/slow → 응답 지연 — 이전 경로 유지
